import org.gradle.kotlin.dsl.create

/**
 * Registers the [MagiskDistributionExtension] on the root project.
 *
 * Apply this once in the root build script and declare the flavor matrix there. Android
 * modules then pick it up through `magisk.android.distribution`, whose accessor is
 * generated by this plugin, so a consumer gets a typed DSL with no extra classpath wiring.
 */

val magiskDistribution = extensions.create<MagiskDistributionExtension>("magiskDistribution").apply {
    dimension.convention("distribution")
    dynamicFeatureFlavors.convention(emptyList())
    preferInjectedCommitHash.convention(false)
}
